Layer.OnCommand:
%function(self)
	self:x(SCREEN_LEFT+150);
	self:y(SCREEN_TOP+40);
	self:zoom(0.5)
	UpdateCoinAmmount = true;
	end

%function(self)
		if UpdateCoinAmmount then
			self:sleep(1.3);
			self:linear(0.3);
			self:diffusealpha(1)
			self:sleep(0.6);
			self:linear(0.3);
			self:diffusealpha(0)
		end
		end
